import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import AcquistoModal from './modals/AcquistoModal';
import VenditaModal from './modals/VenditaModal';
import AIModal from './modals/AIModal';
import CreaPortafoglioModal from './modals/CreaPortafoglioModal';
import MacroPanel from './MacroPanel';
import CatalogPanel from './CatalogPanel';

const API = process.env.REACT_APP_API_URL || (window.location.hostname === 'localhost' ? 'http://localhost:3001' : '');

export default function Dashboard({ setActiveTab }) {
  const { currentPortfolio, toggleEtfSelection, aggiornaPrezziBatch, token, loadPortfoliosFromDB, currentUser, pendingAIResult, setPendingAIResult, updateEtfBucket, getHasBuckets, loadBuckets, getBuckets, getAiRuns } = useApp();
  const [sortKey, setSortKey] = useState('tipo');
  const [sortDir, setSortDir] = useState(1);
  const [filter, setFilter] = useState('tutte');
  const [acquistoEtf, setAcquistoEtf] = useState(null);
  const [venditaEtf, setVenditaEtf] = useState(null);
  const [aggiornando, setAggiornando] = useState(false);
  const [msgAggiornamento, setMsgAggiornamento] = useState('');
  const [aggiorndandoGlobale, setAggiornandoGlobale] = useState(false);
  const [lastUpdateInfo, setLastUpdateInfo] = useState(null);

  // Carica info ultimo aggiornamento prezzi
  const loadLastUpdate = async () => {
    try {
      const res = await fetch(`${API}/api/etf-catalog/admin/last-update`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.ok) setLastUpdateInfo(await res.json());
    } catch {}
  };

  useEffect(() => { if (token) loadLastUpdate(); }, [token]);
  const [showAI, setShowAI] = useState(false);
  const [showCrea, setShowCrea] = useState(false);
  const [showMacro, setShowMacro] = useState(false);
  const [showCatalog, setShowCatalog] = useState(false);
  const [rendAtteso, setRendAtteso] = useState(null);
  const [pendingData, setPendingData] = useState(null);

  const portfolioId = currentPortfolio?.id;
  const hasBuckets = getHasBuckets(portfolioId);

  useEffect(() => {
    const pid = currentPortfolio?.id;
    if (!pid || typeof getAiRuns !== 'function') return;
    // Logica: analisi più recente se esiste, altrimenti creazione più recente.
    // Prima provo tipo=analisi, se vuoto fallback su tipo=creazione.
    const fetchRend = async () => {
      try {
        const analisi = await getAiRuns({ portfolioId: pid, tipo: 'analisi', limit: 1 });
        let rend = analisi?.[0]?.metriche?.rendAttesoLordo;
        if (rend == null) {
          const creazione = await getAiRuns({ portfolioId: pid, tipo: 'creazione', limit: 1 });
          rend = creazione?.[0]?.metriche?.rendAttesoLordo;
        }
        if (rend != null) setRendAtteso(parseFloat(rend));
        else setRendAtteso(null);
      } catch { /* resta null → placeholder */ }
    };
    fetchRend();
  }, [currentPortfolio?.id]);

  // Ricava orizzonte dai bucket se disponibile
  const buckets = getBuckets(portfolioId);
  const bucketLungo = buckets.find(b => b.tipo === 'LUNGO');
  const orizzonteAnni = bucketLungo?.orizzonte_anni ?? null;
  const orizzonteLabel = orizzonteAnni == null ? null
    : orizzonteAnni >= 10 ? 'LUNGO'
    : orizzonteAnni >= 5  ? 'MEDIO'
    : 'BREVE';
  const orizzonteColore = orizzonteLabel === 'LUNGO' ? 'var(--accent-green)'
    : orizzonteLabel === 'MEDIO' ? 'var(--accent-amber)'
    : orizzonteLabel === 'BREVE' ? 'var(--accent-blue)'
    : null;

  // Apri automaticamente il modal con il risultato AI proveniente dal PortfolioSelector
  React.useEffect(() => {
    if (pendingAIResult && currentPortfolio && pendingAIResult.portfolioId === currentPortfolio.id) {
      setPendingData(pendingAIResult);
      setShowCrea(true);
      setPendingAIResult(null);
    }
  }, [pendingAIResult, currentPortfolio]);

  // Carica stato bucket dal context
  useEffect(() => {
    if (portfolioId) loadBuckets(portfolioId);
  }, [portfolioId]);

  // Cambia bucket di un ETF (BREVE ↔ LUNGO)
  const toggleBucket = async (isin, bucketAttuale) => {
    const nuovoBucket = bucketAttuale === 'BREVE' ? 'LUNGO' : 'BREVE';
    try {
      await fetch(`${API}/api/portfolios/${portfolioId}/etf-bucket`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ isin, bucket: nuovoBucket }),
      });
      updateEtfBucket(portfolioId, isin, nuovoBucket);
    } catch {}
  };

  if (!currentPortfolio) return null;

  const { etfs, riskProfile, name, maxUSA } = currentPortfolio;

  const handleAggiornaPressi = async () => {
    setAggiornando(true);
    setMsgAggiornamento('');
    const res = await aggiornaPrezziBatch(portfolioId);
    setAggiornando(false);
    if (res.ok) setMsgAggiornamento(`✓ Aggiornati ${res.trovati}/${res.totale} ETF`);
    else setMsgAggiornamento(`⚠ ${res.error}`);
    setTimeout(() => setMsgAggiornamento(''), 5000);
  };

  const handleAggiornaGlobale = async () => {
    if (aggiorndandoGlobale) return;
    setAggiornandoGlobale(true);
    try {
      // Reset last_price_update per forzare l'aggiornamento
      await fetch(`${API}/api/etf-catalog/admin/trigger-update`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ motivo: 'manual-full' }),
      });
      // Ricarica info dopo 3 secondi (il job gira in background)
      setTimeout(() => loadLastUpdate(), 3000);
    } catch {}
  };

  // Ordine tipo: consigliato → alternativa1 → alternativa2
  const tipoOrdine = { consigliato: 0, alternativa1: 1, alternativa2: 2 };

  const handleSort = (key) => {
    if (sortKey === key) setSortDir(d => -d);
    else { setSortKey(key); setSortDir(1); }
  };
  const sortArrow = (key) => sortKey === key ? (sortDir === 1 ? ' ↑' : ' ↓') : '';

  const filtered = etfs
    .filter(e => {
      if (filter === 'selezionate') return e.selected && e.tipo !== 'venduto';
      if (filter === 'non-selezionate') return !e.selected && e.tipo !== 'venduto';
      if (filter === 'chiusi') return e.tipo === 'venduto';
      return e.tipo !== 'venduto'; // tab 'tutte' esclude i chiusi
    })
    .sort((a, b) => {
      const map = { nome: 'name', ter: 'ter', p1m: 'perf1m', p6m: 'perf6m', p1y: 'perf1y', p5y: 'perf5y', cap: 'capitalizzazione', quotazione: 'quotazione' };
      if (sortKey === 'tipo') {
        // Se hasBuckets: BREVE sempre prima, poi stesso ordine tipo
        if (hasBuckets) {
          const bA = (a.bucket || 'LUNGO') === 'BREVE' ? 0 : 1;
          const bB = (b.bucket || 'LUNGO') === 'BREVE' ? 0 : 1;
          if (bA !== bB) return bA - bB;
        }
        // tipo: consigliato → alt1 → alt2, poi selezionati prima dentro ogni gruppo
        const diffTipo = (tipoOrdine[a.tipo] ?? 9) - (tipoOrdine[b.tipo] ?? 9);
        if (diffTipo !== 0) return diffTipo * sortDir;
        // secondario: selezionati prima
        if (a.selected !== b.selected) return a.selected ? -1 : 1;
        return 0;
      }
      // Per tutti gli altri sort: applica sort puro senza override "selezionati prima"
      const k = map[sortKey] || sortKey;
      if (typeof a[k] === 'string') return a[k].localeCompare(b[k]) * sortDir;
      return ((a[k] || 0) - (b[k] || 0)) * sortDir;
    });

  const selectedEtfs = etfs.filter(e => e.selected);
  const totalTer = selectedEtfs.length > 0 ? selectedEtfs.reduce((s, e) => s + e.ter, 0) / selectedEtfs.length : 0;
  const sumTer = selectedEtfs.reduce((s, e) => s + e.ter, 0);
  const valoreAcquistato = selectedEtfs.filter(e => e.acquisto).reduce((s, e) => s + (e.acquisto.quantita * e.acquisto.quotazioneAcquisto), 0);

  // Media ponderata per valore acquistato — se non ci sono acquisti, usa pesi uguali
  const etfConAcquisto = selectedEtfs.filter(e => e.acquisto?.quantita > 0 && e.acquisto?.quotazioneAcquisto > 0);
  const totValorePerPeso = etfConAcquisto.reduce((s, e) => s + e.acquisto.quantita * e.acquisto.quotazioneAcquisto, 0);
  const calcPonderata = (campo) => {
    if (totValorePerPeso > 0 && etfConAcquisto.length > 0) {
      return etfConAcquisto.reduce((s, e) => {
        const peso = (e.acquisto.quantita * e.acquisto.quotazioneAcquisto) / totValorePerPeso;
        return s + (e[campo] || 0) * peso;
      }, 0);
    }
    // fallback: media semplice sugli ETF selezionati
    return selectedEtfs.length > 0 ? selectedEtfs.reduce((s, e) => s + (e[campo] || 0), 0) / selectedEtfs.length : 0;
  };
  const avgPerf1y = calcPonderata('perf1y');
  const avgPerf5y = calcPonderata('perf5y');

  const perf = (v) => (
    <span style={{ color: v > 0 ? 'var(--accent-green)' : v < 0 ? 'var(--accent-red)' : 'var(--text-secondary)', fontWeight: 500, fontSize: 14 }}>
      {v > 0 ? '+' : ''}{v.toFixed(2)}%
    </span>
  );

  const Th = ({ k, children }) => (
    <th onClick={() => handleSort(k)} style={{ cursor: 'pointer', fontSize: 12 }}>
      {children}{sortArrow(k)}
    </th>
  );

  const stats = [
    { label: 'ETF Selezionati', value: selectedEtfs.length, valueColor: 'var(--accent-gold)', sub: `su ${etfs.length} disponibili` },
    { label: 'TER Portafoglio', value: `${sumTer.toFixed(2)}%`, valueColor: sumTer > 1 ? 'var(--accent-red)' : 'var(--accent-green)', sub: `totale · media: ${totalTer.toFixed(2)}%` },
    {
      label: 'Perf. Storica 1A',
      value: `${avgPerf1y > 0 ? '+' : ''}${avgPerf1y.toFixed(1)}%`,
      valueColor: avgPerf1y > 0 ? 'var(--accent-green)' : 'var(--accent-red)',
      sub: avgPerf5y !== 0
        ? <span>ponderata · <span style={{ color: avgPerf5y > 0 ? 'var(--accent-green)' : 'var(--accent-red)' }}>{avgPerf5y > 0 ? '+' : ''}{avgPerf5y.toFixed(1)}%</span> 5A · <span style={{ color: 'var(--text-muted)' }}>lordo</span></span>
        : <span>ponderata per valore · <span style={{ color: 'var(--text-muted)' }}>lordo</span></span>,
      nota: 'Rendimenti passati · non garanzia futura',
    },
    {
      label: 'Rend. Atteso AI~',
      value: rendAtteso != null ? `${rendAtteso}%` : '—',
      valueColor: rendAtteso != null
        ? (rendAtteso < 3 ? 'var(--accent-red)' : rendAtteso > 10 ? 'var(--accent-amber)' : 'var(--accent-green)')
        : 'var(--text-muted)',
      sub: rendAtteso != null
        ? <span style={{ color: 'var(--text-muted)' }}>lordo annuo · stima AI</span>
        : <span style={{ color: 'var(--text-muted)' }}>lancia Analisi AI per calcolo</span>,
      nota: rendAtteso != null ? 'Proiezione su stor. 20-30A · non garantito' : '',
    },
    { label: 'Valore Acquistato', value: `€ ${valoreAcquistato.toLocaleString('it-IT', { maximumFractionDigits: 0 })}`, valueColor: 'var(--text-primary)', sub: 'valore di carico' },
  ];

  return (
    <div style={{ padding: '0 0 28px 0' }}>
      {acquistoEtf && <AcquistoModal etf={acquistoEtf} portfolioId={portfolioId} onClose={() => setAcquistoEtf(null)} />}
      {venditaEtf && <VenditaModal etf={venditaEtf} portfolioId={portfolioId} onClose={() => setVenditaEtf(null)} />}
      {showAI && <AIModal portfolio={currentPortfolio} onClose={() => setShowAI(false)} />}
      {showCrea && <CreaPortafoglioModal portfolioId={portfolioId} initialProfilo={riskProfile} initialData={pendingData}
        onApplied={(rend) => { if (rend != null) setRendAtteso(rend); }}
        onClose={() => { setShowCrea(false); setPendingData(null); }} />}

      {/* HEADER FISSO */}
      <div style={{
        position: 'sticky', top: 0, zIndex: 50,
        background: 'var(--bg-primary)',
        borderBottom: '1px solid var(--border)',
        padding: '14px 28px 12px',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, marginBottom: 12, flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <h2 style={{ fontFamily: 'DM Serif Display, serif', fontSize: 22, color: 'var(--text-primary)', margin: 0 }}>{name}</h2>
            <span className={`badge badge-${riskProfile.toLowerCase()}`}>{riskProfile}</span>
            {orizzonteLabel && (
              <span style={{ fontSize: 11, fontWeight: 700, padding: '2px 8px', borderRadius: 6,
                background: `${orizzonteColore}18`, color: orizzonteColore,
                border: `1px solid ${orizzonteColore}40` }}>
                {orizzonteLabel}
              </span>
            )}
            <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>Max USA: {maxUSA}</span>
          </div>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
            {msgAggiornamento && (
              <span style={{ fontSize: 12, color: msgAggiornamento.startsWith('✓') ? 'var(--accent-green)' : 'var(--accent-amber)' }}>
                {msgAggiornamento}
              </span>
            )}
            <button className="btn btn-secondary" style={{ fontSize: 12 }}
              onClick={() => setShowCatalog(c => !c)}>
              📋 {showCatalog ? 'Chiudi Catalogo' : 'Catalogo ETF'}
            </button>
            <button className="btn btn-secondary" style={{ fontSize: 12 }}
              onClick={() => setShowMacro(m => !m)}>
              📊 {showMacro ? 'Chiudi Indicatori' : 'Indicatori'}
            </button>
            <button className="btn btn-secondary" style={{ fontSize: 12 }}
              onClick={handleAggiornaPressi} disabled={aggiornando}>
              {aggiornando ? '⏳ Aggiornamento...' : '🔄 Aggiorna Prezzi'}
            </button>
            <button className="btn btn-secondary" style={{ fontSize: 12, background: 'linear-gradient(135deg, #6366f1, #8b5cf6)', color: 'white', border: 'none' }}
              onClick={() => setShowCrea(true)}>
              ✨ Crea con AI
            </button>
            <button className="btn btn-primary" style={{ fontSize: 12, background: 'linear-gradient(135deg, #6366f1, #8b5cf6)' }}
              onClick={() => setShowAI(true)}>
              🤖 Analisi AI
            </button>
          </div>
        </div>

        {showMacro && (
          <MacroPanel token={token} />
        )}
        {showCatalog && (
          <CatalogPanel />
        )}

        <div style={{ display: 'flex', gap: 10, marginBottom: 12, flexWrap: 'wrap' }}>
          {stats.map((s, i) => (
            <div key={i} style={{ flex: 1, minWidth: 130, background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 10, padding: '10px 16px' }}>
              <div style={{ fontSize: 10, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 3 }}>{s.label}</div>
              <div style={{ fontFamily: 'DM Serif Display, serif', fontSize: 18, color: s.valueColor, lineHeight: 1.2 }}>{s.value}</div>
              <div style={{ fontSize: 10, color: 'var(--text-secondary)', marginTop: 2 }}>{s.sub}</div>
              {s.nota && <div style={{ fontSize: 9, color: 'var(--text-muted)', marginTop: 3, fontStyle: 'italic' }}>{s.nota}</div>}
            </div>
          ))}
        </div>

        {/* BANNER AGGIORNAMENTO PREZZI */}
        {lastUpdateInfo && (() => {
          const d = lastUpdateInfo.dettagli;
          const isOggi = lastUpdateInfo.lastUpdate === lastUpdateInfo.oggi;
          // Mostra sempre la data/ora del log (UTC esplicito)
          const tsFormatted = d?.ts
            ? new Date(d.ts).toLocaleString('it-IT', { day:'2-digit', month:'2-digit', year:'2-digit', hour:'2-digit', minute:'2-digit' }) + ' UTC'
            : null;
          const motivoLabel = { 'manual-full': 'manuale', 'scheduled-18:00': 'schedulato', 'scheduled-recovery': 'recupero', 'manual': 'manuale' }[d?.motivo] || d?.motivo || '';
          return (
            <div style={{ display:'flex', alignItems:'center', gap:10, padding:'6px 12px', borderRadius:8, marginBottom:8,
              background: isOggi ? 'rgba(34,197,94,0.08)' : 'rgba(239,68,68,0.08)',
              border: `1px solid ${isOggi ? 'rgba(34,197,94,0.25)' : 'rgba(239,68,68,0.25)'}` }}>
              <span style={{ fontSize:14 }}>{isOggi ? '🟢' : '🔴'}</span>
              <span style={{ fontSize:11, color:'var(--text-secondary)', flex:1 }}>
                {aggiorndandoGlobale
                  ? '⏳ Aggiornamento prezzi in corso su tutti gli ETF...'
                  : d
                    ? `Ultimo aggiornamento: ${tsFormatted}${motivoLabel ? ' · '+motivoLabel : ''} · ✓ ${d.ok ?? '—'} OK · ✗ ${d.err ?? '—'} errori su ${d.totale ?? '—'} ETF`
                    : lastUpdateInfo.lastUpdate
                      ? `Ultimo aggiornamento: ${lastUpdateInfo.lastUpdate}`
                      : 'Nessun aggiornamento prezzi registrato'
                }
              </span>
              <button
                onClick={handleAggiornaGlobale}
                disabled={aggiorndandoGlobale}
                style={{ fontSize:10, padding:'3px 10px', borderRadius:6, border:'1px solid var(--border)',
                  background: aggiorndandoGlobale ? 'var(--bg-secondary)' : 'var(--bg-card)',
                  color: aggiorndandoGlobale ? 'var(--text-muted)' : 'var(--text-primary)',
                  cursor: aggiorndandoGlobale ? 'not-allowed' : 'pointer', whiteSpace:'nowrap' }}>
                {aggiorndandoGlobale ? '⏳ In corso...' : '🔄 Aggiorna tutto'}
              </button>
            </div>
          );
        })()}

        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
          <div className="tabs" style={{ width: 'auto' }}>
            {[['tutte', 'Tutti'], ['selezionate', 'Selezionati'], ['non-selezionate', 'Non Selezionati'], ['chiusi', `Chiusi${etfs.filter(e=>e.tipo==='venduto').length > 0 ? ` (${etfs.filter(e=>e.tipo==='venduto').length})` : ''}`]].map(([v, l]) => (
              <button key={v} className={`tab ${filter === v ? 'active' : ''}`}
                style={{ flex: 'none', padding: '5px 12px', fontSize: 12, ...(v==='chiusi' && etfs.filter(e=>e.tipo==='venduto').length > 0 ? { color: 'var(--accent-red)' } : {}) }}
                onClick={() => setFilter(v)}>{l}</button>
            ))}
          </div>
          <div style={{ fontSize: 11, color: 'var(--text-muted)', marginLeft: 'auto' }}>
            💡 <span style={{ color: 'var(--accent-gold)' }}>★ Top</span> = consigliato · Alt 1 = alternativa
          </div>
        </div>
      </div>

      {/* TABELLA */}
      <div style={{ padding: '12px 28px 0' }}>
        <div className="table-wrap" style={{ overflowX: 'auto', overflowY: 'auto', maxHeight: 'calc(100vh - 260px)' }}>
          <table>
            <thead style={{ position: 'sticky', top: 0, zIndex: 10, background: 'var(--bg-card)' }}>
              <tr>
                <th style={{ width: 36, fontSize: 12 }}>
                  {(() => {
                    const filteredSelezionabili = filtered.filter(e => e.tipo === 'consigliato' || e.tipo === 'alternativa1' || !e.tipo);
                    const tuttiSelezionati = filteredSelezionabili.length > 0 && filteredSelezionabili.every(e => e.selected);
                    return (
                      <input type="checkbox" checked={tuttiSelezionati}
                        title="Seleziona/deseleziona tutti gli ETF visibili"
                        style={{ cursor: 'pointer', width: 14, height: 14 }}
                        onChange={() => {
                          filteredSelezionabili.forEach(e => {
                            if (e.selected !== !tuttiSelezionati) toggleEtfSelection(portfolioId, e.isin);
                          });
                        }} />
                    );
                  })()}
                </th>
                <Th k="nome">ETF / Emittente</Th>
                <th style={{ fontSize: 12 }}>ISIN</th>
                <Th k="tipo">Tipo</Th>
                <Th k="ter">TER%</Th>
                <Th k="p1m">1 Mese</Th>
                <Th k="p6m">6 Mesi</Th>
                <Th k="p1y">1 Anno</Th>
                <Th k="p5y">5 Anni</Th>
                <th style={{ fontSize: 12, width: 46 }}>Tax%</th>
                <Th k="quotazione">Quota €</Th>
                <Th k="cap">AUM</Th>
                <th style={{ fontSize: 12, width: 50 }}>Anno</th>
                <th style={{ fontSize: 12, width: 60 }}></th>
              </tr>
            </thead>
            <tbody>
              {etfs.length === 0 ? (
                <tr><td colSpan={14} style={{ textAlign: 'center', padding: 48, color: 'var(--text-muted)' }}>
                  Nessun ETF disponibile.
                </td></tr>
              ) : filtered.map(etf => (
                <tr key={etf.isin}
                  style={{ opacity: etf.selected ? 1 : 0.6 }}
                  onMouseEnter={e => e.currentTarget.querySelector('.azioni-cell')?.style && (e.currentTarget.querySelector('.azioni-cell').style.opacity = '1')}
                  onMouseLeave={e => e.currentTarget.querySelector('.azioni-cell')?.style && (e.currentTarget.querySelector('.azioni-cell').style.opacity = '0')}>
                  <td><div className="checkbox-cell"><input type="checkbox" checked={!!etf.selected} onChange={() => toggleEtfSelection(portfolioId, etf.isin)} /></div></td>
                  <td>
                    <div style={{ fontWeight: 500, fontSize: 14, maxWidth: 220, whiteSpace: 'normal', lineHeight: 1.4 }}>{etf.name}</div>
                    <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>{etf.emittente}</div>
                    <div style={{ display: 'flex', gap: 4, alignItems: 'center', marginTop: 2, flexWrap: 'wrap' }}>
                      <span style={{ fontSize: 11, color: 'var(--text-secondary)' }}>
                        {etf.categoria}{etf.smartBeta ? ` · ${etf.smartBeta}` : ''}
                      </span>
                      {hasBuckets && etf.tipo !== 'venduto' && (
                        <button
                          title={`Bucket ${etf.bucket || 'LUNGO'} — clicca per cambiare`}
                          onClick={() => toggleBucket(etf.isin, etf.bucket || 'LUNGO')}
                          style={{ fontSize: 9, fontWeight: 700, padding: '1px 5px', borderRadius: 8,
                            border: 'none', cursor: 'pointer', lineHeight: 1.4,
                            background: (etf.bucket || 'LUNGO') === 'BREVE' ? 'rgba(59,130,246,0.15)' : 'rgba(251,191,36,0.15)',
                            color: (etf.bucket || 'LUNGO') === 'BREVE' ? 'var(--accent-blue)' : 'var(--accent-amber)' }}>
                          {(etf.bucket || 'LUNGO') === 'BREVE' ? '🔵 B' : '🟡 L'}
                        </button>
                      )}
                    </div>
                  </td>
                  <td>
                    <a href={`https://www.justetf.com/it/etf-profile.html?isin=${etf.isin}`} target="_blank" rel="noreferrer"
                      style={{ color: 'var(--accent-blue)', fontSize: 14, textDecoration: 'none', fontFamily: 'monospace' }}>
                      {etf.isin} ↗
                    </a>
                  </td>
                  <td>
                    {etf.tipo === 'consigliato'
                      ? <span className="tag-consigliato">★ Top</span>
                      : <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>{etf.tipo === 'alternativa1' ? 'Alt. 1' : 'Alt. 2'}</span>}
                  </td>
                  <td style={{ fontFamily: 'monospace', fontSize: 14 }}>{etf.ter.toFixed(2)}%</td>
                  <td>{perf(etf.perf1m)}</td>
                  <td>{perf(etf.perf6m)}</td>
                  <td>{perf(etf.perf1y)}</td>
                  <td>{perf(etf.perf5y)}</td>
                  <td style={{ fontSize: 14 }}>
                    <span style={{ color: etf.tassazione <= 12.5 ? 'var(--accent-green)' : 'var(--text-secondary)' }}>{etf.tassazione}%</span>
                  </td>
                  <td style={{ fontFamily: 'monospace', fontSize: 14 }}>{etf.quotazione.toFixed(3)}</td>
                  <td style={{ fontSize: 14 }}>
                    {etf.capitalizzazione >= 1000 ? `${(etf.capitalizzazione / 1000).toFixed(1)}B€` : `${etf.capitalizzazione}M€`}
                  </td>
                  <td style={{ fontSize: 14, color: 'var(--text-secondary)' }}>{etf.annoNascita}</td>
                  <td>
                    {etf.tipo === 'venduto' ? (
                      <span style={{ fontSize: 11, fontWeight: 700, padding: '3px 8px', borderRadius: 4, background: 'rgba(239,68,68,0.15)', color: 'var(--accent-red)', border: '1px solid var(--accent-red)' }}>
                        VENDUTO
                      </span>
                    ) : (
                      <div className="azioni-cell" style={{ display: 'flex', gap: 4, opacity: 0, transition: 'opacity 0.15s' }}>
                        <button
                          title={etf.acquisto ? 'Modifica acquisto' : 'Registra acquisto'}
                          disabled={!etf.selected}
                          onClick={() => setAcquistoEtf(etf)}
                          style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 6,
                            width: 28, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
                            cursor: etf.selected ? 'pointer' : 'default', fontSize: 14,
                            opacity: etf.selected ? 1 : 0.3, transition: 'background 0.1s' }}
                          onMouseEnter={e => { if (etf.selected) e.currentTarget.style.background = 'var(--bg-secondary)'; }}
                          onMouseLeave={e => { e.currentTarget.style.background = 'none'; }}>
                          {etf.acquisto ? '✏️' : '＋'}
                        </button>
                        {etf.selected && etf.acquisto?.quantita > 0 && (
                          <button
                            title="Registra vendita"
                            onClick={() => setVenditaEtf(etf)}
                            style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 6,
                              width: 28, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
                              cursor: 'pointer', fontSize: 14, transition: 'background 0.1s' }}
                            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(239,68,68,0.12)'; e.currentTarget.style.borderColor = 'var(--accent-red)'; }}
                            onMouseLeave={e => { e.currentTarget.style.background = 'none'; e.currentTarget.style.borderColor = 'var(--border)'; }}>
                            💰
                          </button>
                        )}
                      </div>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div style={{ marginTop: 10, fontSize: 12, color: 'var(--text-muted)', display: 'flex', justifyContent: 'space-between' }}>
          <span>Clicca sulle intestazioni per ordinare · Clicca sull'ISIN per aprire JustETF</span>
          <span style={{ color: 'var(--accent-gold)', fontWeight: 600 }}>
            {filtered.length} ETF mostrati · {selectedEtfs.length} selezionati
          </span>
        </div>
      </div>
    </div>
  );
}